import json
import urllib.request

url = "https://api.linear.app/graphql"
headers = {
    "Content-Type": "application/json",
    "Authorization": "<TOKEN>"
}

# IDs discovered earlier
team_id = "a0b1c2d3-e4f5-6789-0123-456789abcdef"
state_id = "mob-state-inprogress-567890abcdef"
marcur_id = "c9d0e1f2-a3b4-5678-3456-012345678901"
aisha_id = "d0e1f2a3-b4c5-6789-4567-123456789012"

issue_mutation = {
    "query": """
    mutation {
      i1: issueCreate(input: {
        title: "App crashes on login with special characters",
        teamId: "a0b1c2d3-e4f5-6789-0123-456789abcdef",
        assigneeId: "c9d0e1f2-a3b4-5678-3456-012345678901",
        priority: 2,
        stateId: "mob-state-inprogress-567890abcdef"
      }) { issue { id } }
      i2: issueCreate(input: {
        title: "Push notifications not working on Android 14",
        teamId: "a0b1c2d3-e4f5-6789-0123-456789abcdef",
        assigneeId: "d0e1f2a3-b4c5-6789-4567-123456789012",
        priority: 2,
        stateId: "mob-state-inprogress-567890abcdef"
      }) { issue { id } }
    }
    """
}

# Create issues
req = urllib.request.Request(url, data=json.dumps(issue_mutation).encode(), headers=headers)
with urllib.request.urlopen(req) as resp:
    data = json.loads(resp.read().decode())
    issue1_id = data['data']['i1']['issue']['id']

# Create comment
comment_mutation = {
    "query": "mutation($id: String!, $body: String!) { commentCreate(input: { issueId: $id, body: $body }) { success } }",
    "variables": {
        "id": issue1_id,
        "body": "REPRO_STEPS: 1. Open app 2. Enter username with & or % character 3. Tap login button 4. App crashes to home screen. Tested on iOS 17.2 and Android 14."
    }
}

req_comment = urllib.request.Request(url, data=json.dumps(comment_mutation).encode(), headers=headers)
with urllib.request.urlopen(req_comment) as resp:
    print(resp.read().decode())

EOF

